import{_ as t,c as r,o as a,aj as o,ao as i,ap as n}from"./chunks/framework.C2N4vG9O.js";const p=JSON.parse('{"title":"Introducing Torch-RecHub","description":"How features, models and trainers fit together in Torch-RecHub.","frontmatter":{"title":"Introducing Torch-RecHub","description":"How features, models and trainers fit together in Torch-RecHub."},"headers":[],"relativePath":"guide/intro.md","filePath":"en/guide/intro.md"}'),c={name:"guide/intro.md"};function d(h,e,s,l,u,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introducing-torch-rechub" tabindex="-1">Introducing Torch-RecHub <a class="header-anchor" href="#introducing-torch-rechub" aria-label="Permalink to “Introducing Torch-RecHub”">​</a></h1><p>Torch-RecHub implements retrieval, ranking, multi-task and generative recommendation models in PyTorch. A good first experiment is to train DeepFM on the bundled ad-click sample and see how it turns one ad impression into a click probability. <a href="/torch-rechub/guide/quick_start.html">Quick start</a></p><p><img src="'+i+'" alt="Torch-RecHub banner"></p><h2 id="framework-architecture" tabindex="-1">Framework architecture <a class="header-anchor" href="#framework-architecture" aria-label="Permalink to “Framework architecture”">​</a></h2><p><img src="'+n+'" alt="Torch-RecHub framework architecture"></p><p>When you bring your own data, three parts of the code matter first. Feature definitions tell the model how to read each column. For example, <code>item_id</code> looks up a row in an embedding table, while <code>price</code> goes in as a number. The model&#39;s <code>forward</code> method combines those inputs. The trainer reads batches, computes validation metrics and saves weights. To change how a model scores an example, start with its <code>forward</code> method. <a href="/torch-rechub/core/features.html">Feature definitions</a> · <a href="/torch-rechub/core/evaluation.html">Training and evaluation</a></p><h2 id="choose-a-model-for-your-task" tabindex="-1">Choose a model for your task <a class="header-anchor" href="#choose-a-model-for-your-task" aria-label="Permalink to “Choose a model for your task”">​</a></h2><table tabindex="0"><thead><tr><th>What do you need to do?</th><th>Where to start</th></tr></thead><tbody><tr><td>Select a short list of candidates for each user from a large catalog</td><td><a href="/torch-rechub/tutorials/retrieval.html">Retrieve candidates with DSSM</a></td></tr><tr><td>Order existing candidates by how likely the user is to click</td><td><a href="/torch-rechub/tutorials/ctr.html">Rank candidates with DeepFM</a></td></tr><tr><td>Learn from both click and purchase labels on the same impression</td><td><a href="/torch-rechub/tutorials/pipeline.html">Multi-task learning</a></td></tr><tr><td>Predict the next item from a sequence of timestamped interactions</td><td><a href="/torch-rechub/models/generative.html">Sequential and generative models</a></td></tr></tbody></table><p>You can run the introductory examples on a CPU. For an NVIDIA GPU, AMD GPU or Huawei Ascend NPU, install the PyTorch build that matches the device. After training, you can export a ranker to ONNX for inference. With a two-tower model, you can also compute user and item vectors separately for retrieval. <a href="/torch-rechub/guide/install.html">Installation</a> · <a href="/torch-rechub/serving/demo.html">Serving example</a></p>',9)])])}const b=t(c,[["render",d]]);export{p as __pageData,b as default};
